={{ (() => { 
  try {
    // 1. محاولة جلب البيانات مباشرة من أول نتيجة للمفسر الطبي لتفادي تفرع الكاش
    const rawOutput = $('Clinical Interpreter').first().json.output;

    // 2. إذا كانت البيانات نص جيسون منسق، نقوم بفكها وتنظيفها
    if (rawOutput) {
      return typeof rawOutput === 'string' ? JSON.parse(rawOutput) : rawOutput;
    }
  } catch (e) {
    // 3. حل احتياطي في حال حدوث أي خطأ غير متوقع في الفك
    return $('Clinical Interpreter').first().json.output || "No clinical data found";
  }
  return "No clinical data found";
})() }}

