// الحصول على تاريخ اليوم بتنسيق YYYY-MM-DD
const today = new Date().toISOString().split('T')[0]; 

// فلترة الصفوف التي تم تسجيلها اليوم فقط
const todaysCases = items.filter(item => {
    const rowDate = item.json.Date; // تأكد من كتابة اسم عمود التاريخ عندك بالظبط بدلاً من Date
    return rowDate && rowDate.includes(today);
});

return [{
    json: {
        total_cases: todaysCases.length
    }
}];
